"""Complete Polish egg, chicken and herring dishes and two Swedish cooked sauces."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

merges=[];updatedids=[]
def merge(n,r,reason):
 s=src(n);aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason=reason)
 if s['id'] not in r['sourceAliases']:r['sourceAliases'].append(s['id']);r['source']+=' Equivalent source retained: '+s['recipe']['source']
 records.pop(s['id'],None);merges.append(s)

r=add(63,'Jajka w Majonezie — Eggs with Mayonnaise and Green Plum',6,35,'Hard-boiled egg halves are coated in a thick olive-oil mayonnaise and arranged around a halved green plum.',[
 eggs(6),water(1500),I('sauceyolk',27,'g','commercially pasteurized liquid egg yolk for the sauce','Use about one and a half large pasteurized shell-egg yolks, weighed.'),I('oil',114,'g','olive oil, weighed','Use the same weight of a mild sunflower oil.'),vinegar(10),salt(.375),I('sugar',.5,'tsp','white sugar','Use the same amount of caster sugar.'),I('plum',1,'','ripe green plum, such as a greengage','Use a small ripe yellow plum; a firm unripe plum will be much more sour.')],
 boil()+['Keep the peeled eggs covered in the refrigerator while preparing the sauce. Whisk {{sauceyolk}} and {{salt}} in a clean small bowl. Weigh {{oil}} into a jug and whisk it in drop by drop, then in a thin stream once the mixture thickens.','Slowly whisk in {{vinegar}} and {{sugar}} until smooth and the sugar dissolves. This small batch makes a thick coating; keep it refrigerated until assembly.','Cut the cold eggs lengthwise in half. Coat each half with the mayonnaise using a spoon or by dipping it into the bowl, then arrange neatly on a platter. Rinse {{plum}}, halve it and remove the stone. Place the plum halves in the center, as in the original, and serve cold.',END],
 'The original gives no egg count and refers to the sauce chapter, asking for a thicker, saltier mayonnaise than the fish sauce. Six eggs and six snack servings are supplied. The full sauce is based on half the book’s Provensal formula, with 114 g oil, 27 g pasteurized yolk, less vinegar and a little more salt than that half batch to make a coating. These are explicit modern working proportions. The source garnish is a green plum, not an olive; a ripe green-skinned plum is used here. Twelve-minute covered egg cooking replaces the original minimum five-minute instruction so the yolks are firm.');r['category']='Egg dishes';eggsource(r)

r=add(64,'Majonez z Kur — Cold Chicken with Butter and Oil Sauce',8,210,'Poached chicken is served cold under a rich sauce made from clarified butter, flour, chicken broth, olive oil and lemon.',[
 I('chickens',2,'','small oven-ready chickens, about 1.3 kg each, giblets removed','Use the same total weight of bone-in chicken pieces; check each piece reaches the cooking temperature.'),I('poachstock',3000,'ml','unsalted prepared chicken stock for poaching','Use the same volume of unsalted vegetable stock.'),I('onion',1,'','medium onion, peeled and quartered','Use one small cleaned leek per onion.'),I('carrot',1,'','medium carrot, scrubbed and sliced','Use one small peeled parsnip per carrot.'),I('bay',2,'','dried bay leaves','Omit if unavailable.'),I('peppercorns',.5,'tsp','whole black peppercorns','Use the same amount of white peppercorns.'),I('saucestock',250,'ml','cooked chicken poaching broth reserved below, strained and skimmed; not additional stock','Use the same volume of fresh unsalted chicken stock.'),I('butter',113,'g','clarified unsalted butter or plain ghee','Use the same weight of plain unsalted ghee; ordinary butter contains extra water and is not an exact replacement.'),I('flour',16,'g','plain wheat flour','Use the same weight of a plain gluten-free flour blend; thickening may differ.'),I('oil',227,'g','olive oil, weighed','Use the same weight of sunflower oil.'),salt(.5),lemon(30),I('sugar',1,'tsp','white sugar','Use the same amount of caster sugar.')],[
 'Put {{chickens}} in a large pot with {{poachstock}}, {{onion}}, {{carrot}}, {{bay}} and {{peppercorns}}. Add drinking water only if needed to cover. Bring to a gentle simmer, skim foam and poach for about 50–70 minutes, until the thickest breast and thigh meat of each bird reaches 74°C (165°F), away from the bones.',
 'Lift the cooked chickens onto a clean tray. Strain {{saucestock}} from the cooked poaching liquid into a heatproof jug and skim off surface fat. Save this measured portion for the sauce. Cool any remaining broth promptly in shallow containers for another dish, refrigerate and use within 2 days or freeze.',
 'When cool enough to handle, remove the chicken skin and bones and cut the meat into serving pieces. Spread in shallow covered containers and refrigerate promptly, within 2 hours of cooking, until cold, allowing about 1–2 hours. Do not leave whole birds on the counter until cold.',
 'Melt {{butter}} in a small saucepan. Whisk in {{flour}} and cook gently for 2 minutes without browning. Gradually whisk in the measured reserved broth until smooth. Simmer gently for 5 minutes, stirring, until the sauce thickens.',
 'Transfer the sauce to a clean bowl set in cold water, keeping the water out of the sauce. Stir until cool but still soft. Weigh {{oil}} into a jug and whisk it in a few drops at a time, then in a thin stream, until evenly incorporated. If oil pools, stop pouring and whisk until it blends in.',
 'Whisk in {{salt}}, {{lemon}} and {{sugar}} until smooth. Arrange the cold chicken on a platter and spoon the sauce over the pieces. Keep refrigerated until serving.',END],
 'The full original uses two chickens and a quarter funt clarified butter, two spoons flour, a kwaterka of skimmed broth, half a funt oil, a lemon and a teaspoon sugar. The broth word is KWATERKA, not the quart in the extracted translation. This adaptation supplies 250 ml broth, 113 g butter, 16 g flour and 227 g oil as explicit modern working quantities, not universal historical-unit conversions. Chicken size, complete poaching method, aromatics, half teaspoon salt, 30 ml lemon juice and eight servings are supplied. The rich roux-and-oil sauce contains no egg. Prompt portioned chilling replaces extended warm storage.');finish(r)
vi=copy.deepcopy(r['ingredients'])
for i in vi:
 if i['key']=='lemon':i.update(key='vinegar',name='white wine vinegar',substitution='Use the lemon version for a fruitier sauce.')
variant(r,'vinegar-finish','With a vinegar finish',vi,[s.replace('{{lemon}}','{{vinegar}}') for s in r['steps']]);r['notes']+=' The complete vinegar variation retains the source alternative, using a modern working 30 ml in place of the lemon juice.'

r=add(66,'Majonez ze Śledzia — Layered Herring and Potato Platter',4,160,'Slices of cured herring and boiled potato form a small mound, coated with yolk dressing and garnished with pickled mushrooms, gherkins and savory jelly.',[
 I('herring',200,'g','commercial ready-to-eat salt-cured herring fillets, skin and bones removed','Use the same weight of drained ready-to-eat pickled herring for a sharper flavor.'),I('potatoes',600,'g','whole firm waxy potatoes, scrubbed','Use the same weight of another waxy potato variety.'),water(1500),yolks(1),oil(30),I('mustard',.5,'tsp','prepared smooth mustard','Use the same amount of prepared Dijon mustard.'),salt(.125),I('mushrooms',40,'g','ready-to-eat pickled mushrooms, drained and sliced','Use the same weight of extra pickled gherkins.'),I('gherkins',40,'g','pickled gherkins, drained and sliced','Use the same weight of pickled cucumber.'),I('gelatin',3,'g','unflavored powdered gelatin, approximately 200 Bloom','Use the same weight of fish gelatin of similar setting strength.'),I('bloomwater',15,'ml','cold drinking water for gelatin','Use the same volume of cold clear stock.'),I('jellystock',120,'ml','clear unsalted vegetable stock','Use the same volume of clear unsalted fish stock.')],[
 'Start the jelly first. Sprinkle {{gelatin}} over {{bloomwater}} and leave for 5 minutes. Heat {{jellystock}} until steaming, remove from heat and stir in the bloomed gelatin until dissolved. Pour into a shallow dish, cover and refrigerate for about 2 hours until set, then cut into small pieces.',
 'Put {{potatoes}} in a saucepan with {{water}}, adding more drinking water only if needed to cover. Bring to a boil, reduce to a simmer and cook for about 20–30 minutes, until a knife enters the centers easily. Drain. When cool enough to handle, peel and cut into thin slices. Spread in a shallow covered container and refrigerate promptly until cold.',
 'Keep {{herring}} chilled. Check the fillets for remaining pin bones, pat dry and cut into thin slices. Follow any preparation instructions on the ready-to-eat product.',
 'Whisk {{yolks}}, {{mustard}} and {{salt}} in a small clean bowl. Add {{oil}} drop by drop while whisking until evenly blended. This small, low-oil dressing is softer than a high-oil mayonnaise.',
 'On a small chilled platter, alternate layers of cold herring and potato to make a low mound. Spoon the yolk dressing over the surface in a thin coating. Garnish with {{mushrooms}}, {{gherkins}} and the prepared jelly. Serve chilled.',END],
 'The source describes a salted whole herring soaked for eighteen hours, then skinned, deboned and sliced. A modern 200 g portion of commercial ready-to-eat cured fillets replaces that preparation; this is not a method for curing raw fresh fish. The two or three large potatoes become a working 600 g. One yolk and two modern tablespoons oil are retained, with supplied mustard, salt, garnish amounts and four servings. The full Polish original names jelly (galareta), not the capers in the extraction; its missing jelly recipe is supplied in full here. Pickled mushrooms are a modern ready-to-eat garnish choice. Total time includes overlapping jelly-setting and potato-cooling time.');r['category']='Fish';eggsource(r)

CHILL='Transfer to a clean covered container and refrigerate at 4°C (40°F) or colder until serving. Use within 1 day; refrigerate within 2 hours of preparation. Fold in the whipped cream close to serving for the best texture.'
r=add(98,'Idun Kokt Majonnäs — Cooked Mayonnaise with Whipped Cream',8,45,'A cooled butter-and-flour base is enriched with pasteurized yolks, a little oil, vinegar and lemon, then lightened with whipped cream.',[
 I('butter',30,'g','unsalted butter','Use the same weight of salted butter and reduce the added salt.'),I('flour',30,'g','plain wheat flour','Use the same weight of plain gluten-free flour blend; thickening may differ.'),mustard(.25),water(300),yolks(2),vinegar(15),oil(30),lemon(15),I('cream',100,'ml','cold whipping cream, at least 35% fat, measured before whipping','Use the same volume of cold heavy cream.'),salt(2),I('sugar',.5,'tsp','white sugar','Use the same amount of caster sugar.'),I('whitepepper',.25,'tsp','ground white pepper','Use the same amount of ground black pepper for a speckled sauce.')],[
 'Melt {{butter}} in a saucepan over gentle heat. Whisk in {{flour}} and {{mustard}} and cook for 2 minutes without browning. Gradually whisk in {{water}} until smooth, then simmer gently for 10 minutes, stirring frequently to prevent sticking.',
 'Transfer to a clean bowl set over cold water and stir until fully cool, keeping the water out of the sauce. Whisk {{yolks}} into the cooled base a little at a time. Measure {{oil}} into a small jug and slowly whisk it in, alternating with small additions of {{vinegar}} and {{lemon}}, until smooth.',
 'Whip {{cream}} in a separate chilled bowl until firm peaks hold, stopping before it becomes grainy. Fold it into the sauce, then gently stir in {{salt}}, {{sugar}} and {{whitepepper}}. Serve with chilled cooked fish, meat or vegetables.',CHILL],
 'All four imported records reproduce original recipe 443; two stop after cooking the flour base and omit the remaining method. The complete source retains cold yolk addition, so commercially pasteurized yolks are used. The printed gram quantities control: butter is 30 g even though a modern one-and-a-half tablespoon measure could weigh less, and flour is 30 g. The cream is 100 ml liquid before whipping. Two teaspoons salt are the original amount and produce a strongly seasoned sauce; the salt substitution allows reduction. Eight servings fall within the printed six-to-nine range. The source calls this an alternative for people who dislike much oil, but it does contain oil and is not oil-free. Forty-five minutes is a modern estimate including cooling; prolonged hand beating is replaced by mixing until smooth.');eggsource(r)
for n in [97,99,100]:merge(n,r,'Same single Idun original443 and full ingredient formula; shorter entries97/99 omit the second half of the method, retained here from the full original.')

r=add(101,'Hemmets Kokt Majonnässås — Creamy Stock-Based Dressing',12,45,'A strained stock-and-flour base is cooled, enriched with pasteurized yolks and oil, and folded with whipped cream for a soft dressing.',[
 I('butter',21,'g','unsalted butter','Use the same weight of salted butter; the stock may already contain salt.'),I('flour',32,'g','plain wheat flour','Use the same weight of plain gluten-free flour blend; thickening may differ.'),I('mustard',1.5,'tsp','prepared smooth mustard','Use the same amount of prepared Dijon mustard.'),I('whitepepper',.5,'tsp','ground white pepper','Use the same amount of ground black pepper.'),I('stock',300,'ml','prepared chicken stock, lightly salted','Use the same volume of prepared fish stock for the source fish-sauce alternative, or vegetable stock.'),I('sugar',1,'tbsp','white sugar','Use the same amount of caster sugar.'),yolks(3),oil(30),vinegar(45),I('cream',300,'ml','cold whipping cream, at least 35% fat, measured before whipping','Use the same volume of cold heavy cream.')],[
 'Melt {{butter}} in a saucepan over gentle heat. Stir in {{flour}}, {{mustard}} and {{whitepepper}} and cook for about 2 minutes without browning. Gradually whisk in {{stock}}. Simmer gently for about 5 minutes, stirring, until thick and smooth.',
 'Press the cooked sauce through a fine sieve into a clean bowl. Set the bowl over cold water and stir until fully cooled, keeping water out of the sauce. Whisk in {{sugar}}, then add {{yolks}} a little at a time, mixing until smooth.',
 'Measure {{oil}} into a small jug and whisk it into the cooled base drop by drop, alternating with small additions of {{vinegar}}. Whip {{cream}} separately in a chilled bowl until firm peaks hold, stopping before it turns grainy, then fold gently into the sauce. Serve with chilled cooked foods.',CHILL],
 'The two records reproduce original Hemmets recipe 432, which serves twelve. Both stock and cream are three deciliters (300 ml), not the undefined “three parts” in the extraction. The cream is measured as liquid before whipping. The butter and flour become modern working weights of 21 g and 32 g for one-and-a-half and four tablespoons respectively; the book does not supply gram weights here. Prepared mustard is the chosen form because the source does not specify dry powder. Pasteurized yolks preserve its cooled-base method. Stock and fish stock are both explicit source options. Forty-five minutes is a modern preparation estimate. This recipe is distinct from the Idun cooked sauce in its stock, cream proportion, yolk count and seasonings.');eggsource(r)
merge(102,r,'Same complete Hemmets original432, including twelve servings, three deciliters each stock and cream, three yolks and identical cooled-base method.')

assert len(newids)==5 and len(merges)==4
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Complete primary-source dish and component methods, measured ingredients, variants and chilling supplied','repair-batch-032.py'))
for s in merges:db.execute('insert or replace into decisions values(?,?,?,?,?)',(s['id'],s['bodySha256'],'prepared-merge',aliases[s['id']]['reason'],'repair-batch-032.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newAliases=len(merges),totalOverrides=len(records),totalAliases=len(aliases))))

